package ca.yorku.eecs3311.coursepilot.cli; import ca.yorku.eecs3311.coursepilot.application.StudyAgentFacade; import ca.yorku.eecs3311.coursepilot.application.service.LearningHistoryService; import org.springframework.stereotype.Component; import picocli.CommandLine.*;
@Component @Command(name="history",description="Show course learning history",mixinStandardHelpOptions=true) public class HistoryCommand implements Runnable{private final LearningHistoryService history;private final StudyAgentFacade facade;public HistoryCommand(LearningHistoryService h,StudyAgentFacade f){history=h;facade=f;}@Option(names="--course",required=true)String course;public void run(){var c=facade.getCourseByCode(course);history.list(c.id()).forEach(e->System.out.printf("%s %s: %s%n",e.occurredAt(),e.type(),e.detail()));}}
